# LAB-7: calibration gate
c=$(mktemp); printf 'OSC-2\t2026-10-31\nDMM-3\t2027-03-31\nPSU-4\t2026-11-06\n' > "$c"
for case in "OSC-2 2026-11-01 expired" "FG-5 2026-11-01 unlisted"; do
  set -- $case; f=$(mktemp)
  CALIB=$c LOANS=$f bash bin/checkout "$1" test "$2" >/dev/null 2>&1 && { echo "$3 allowed"; fail=1; }
  [ -s "$f" ] && { echo "$3 recorded"; fail=1; }
  rm -f "$f"
done
f=$(mktemp)
CALIB=$c LOANS=$f bash bin/checkout PSU-4 test 2026-11-06 >/dev/null 2>&1 || { echo "due date refused"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "due date not recorded"; fail=1; }
rm -f "$f" "$c"
exit $fail

